class NomPeriodoVacaciones extends BaseNomPeriodoVacaciones {

    /**
     * Obtener un listado de los datos de los períodos de vacaciones.
     * 
     * @param int       $inicio Inicio de la busqueda.
     * @param int       $limite Limite maximo de la busqueda.
     * @return array    Listado de los datos de los períodos de vacaciones.
     */
    public static function obtenerListadoPeriodoVacaciones($inicio = 0, $limite = 10) {
        //Devolviendo el listado de períodos de vacaciones en forma de arreglo.
        return Doctrine_Query::create()
                ->from('NomPeriodoVacaciones')
                ->limit($limite)
                ->offset($inicio)
				->orderBy('tiempootorgar')
                ->fetchArray();
    }

    /**
     * Obtener la cantidad total de períodos de vacaciones.
     * 
     * @return int      Cantidad total de períodos de vacaciones.
     */
    public static function obtenerCantidadTotalPeriodoVacaciones() {

        //Devolviendo la cantidad total de períodos de vacaciones.
        return Doctrine_Query::create()->select('COUNT(idperiodovacaciones) AS cantidad')
                        ->from('NomPeriodoVacaciones')
                        ->fetchOne()
                        ->cantidad;
    }

    /**
     * Obtener el períods de vacaciones dado el identificador.
     * 
     * @param int $idperiodovac         Identificador del períodos de vacaciones.
     * @return NomPeriodoVacaciones     Objeto período de vacaciones. (clase del dominio).
     */
    public static function obtenerObjPeriodoVacDadoId($idperiodovac) {
        return Doctrine::getTable('NomPeriodoVacaciones')->find($idperiodovac);
    }
	
	/**
     * Obtener si existe el período de vacaciones a partir de los días a otorgar y descontar.
     * 
	 * @param int $idpervac    		Identificador del período de vacaciones.
     * @param int $dotorgar    	 	Días a otorgar.
	 * @param int $ddescontar    	Días a descontar.
	 *
     * @return boolean    			Si existe el período de vacaciones.
     */
    public static function existePeriodoVacaciones($idpervac, $dotorgar, $ddescontar) {
		
		$query = Doctrine_Query::create()->select('COUNT(idperiodovacaciones) AS cantidad')
                        ->from('NomPeriodoVacaciones')
						->where("tiempootorgar = ? and tiempodescontar = ? ", array($dotorgar, $ddescontar));
		if($ddescontar){
			$query->addWhere('idperiodovacaciones <> ?', $ddescontar);
		}		
		
		return    $query->fetchOne()->cantidad;
     }

    public static function obtenerPeriodoVacaciones($tiempootorgar) {
        //Devolviendo el listado de períodos de vacaciones en forma de arreglo.
        return Doctrine_Query::create()
            ->from('NomPeriodoVacaciones')
            ->where("tiempootorgar= ? ",$tiempootorgar)
            ->fetchArray();
    }
}
